(()=>{const boot=()=>{try{if(window.__cbGlassBooted)return;window.__cbGlassBooted=true;document.documentElement.classList.add('premium-glass-ready');if(!document.body)return;let glow=document.querySelector('.cb-cursor-glow');if(!glow){glow=document.createElement('div');glow.className='cb-cursor-glow';document.body.appendChild(glow)}const move=e=>{if(innerWidth<900||matchMedia('(prefers-reduced-motion: reduce)').matches)return;glow.style.left=e.clientX+'px';glow.style.top=e.clientY+'px'};window.addEventListener('pointermove',move,{passive:true});const enhance=()=>{try{document.querySelectorAll('.card,.stat,.resource,.road-card,.phase,.continue-card').forEach((el,i)=>{el.classList.add('cb-depth');if(i<18)el.classList.add('cb-shimmer')});document.querySelectorAll('.section-title h3').forEach(el=>{if(el.previousElementSibling?.classList.contains('cb-section-label'))return;const b=document.createElement('span');b.className='cb-section-label';b.textContent='CLOUDBLITZ · PREMIUM EXPERIENCE';el.parentElement?.prepend(b)});document.querySelectorAll('.hero,.cb-orbit-stage').forEach(el=>{if(el.dataset.cbParallax)return;el.dataset.cbParallax='1';el.addEventListener('pointermove',e=>{if(innerWidth<900||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const r=el.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;el.style.transform=`perspective(1100px) rotateX(${y*-1.5}deg) rotateY(${x*2}deg)`},{passive:true});el.addEventListener('pointerleave',()=>el.style.removeProperty('transform'))})}catch(e){console.warn('CloudBlitz premium enhancement skipped:',e)}};let queued=false;const schedule=()=>{if(queued)return;queued=true;setTimeout(()=>{queued=false;enhance()},180)};enhance();new MutationObserver(schedule).observe(document.body,{childList:true,subtree:true})}catch(e){console.warn('CloudBlitz premium glass disabled:',e)}};document.readyState==='loading'?document.addEventListener('DOMContentLoaded',boot):boot()})();